{
  "assessment": "Libya remains deeply fractured by civil war, with the Libyan National Army controlling a majority of the country's regions, including key eastern and southern territories. Our military readiness is moderate, but to unify the country and secure our sovereign mandate, we must systematically rebuild our defense posture while keeping internal order stable. We will maintain our resource policies, reinforce security spending, and apply strategic pressure on the LNA while seeking diplomatic normalization where advantageous.",
  "directives": [
    {
      "type": "set_spending",
      "target": null,
      "amount": 4.0,
      "sub": "military",
      "regions": [],
      "order": "Increase military budget allocation to 4 percent of GDP to support active operations and force readiness."
    },
    {
      "type": "military_mobilize",
      "target": null,
      "amount": 0.5,
      "sub": "",
      "regions": [],
      "order": "Maintain 50 percent mobilization of reserves to support ongoing defensive and offensive operations."
    },
    {
      "type": "resource_policy",
      "target": null,
      "amount": 1.0,
      "sub": "production_level",
      "regions": [],
      "order": "Maintain normal oil production levels to sustain state revenues during the conflict."
    },
    {
      "type": "repression_level",
      "target": null,
      "amount": 0.3,
      "sub": "",
      "regions": [],
      "order": "Keep police and security repression at a moderate level to ensure public order in government-held areas."
    }
  ],
  "cables": [
    {
      "to": "EGY",
      "private": true,
      "text": "We seek constructive dialogue regarding regional stability in Libya and hope to prevent further escalation."
    },
    {
      "to": "DZA",
      "private": true,
      "text": "We value our strong bilateral relations and look forward to continued cooperation on regional security."
    }
  ],
  "public_statement": "The Government of Libya remains firmly committed to restoring national unity, defeating illegal armed factions, and bringing peace and prosperity to all regions of our country.",
  "standing_orders": [
    {
      "when": "at_war",
      "do": {
        "type": "curfew",
        "target": null,
        "amount": 1,
        "sub": "",
        "order": "Enforce a nightly curfew in government-controlled urban areas during active hostilities."
      }
    }
  ],
  "detailed_report": "military"
}
